58	    @Test
59	    void happyFlow_quarantineToReleasedThenRecalled() throws Exception {
60	        String batchKey = "BK-HAPPY-" + unique();
61	        createBatch(batchKey, List.of("外观", "含量", "无菌"), 201);
62	
63	        // 初始隔离，出现在可用列表
64	        assertEquals("QUARANTINED", currentStatus(batchKey));
65	        assertTrue(availableKeys().contains(batchKey));
66	
67	        submitTest(batchKey, testReq("TK-1", "外观", "PASS", "inspect-a"), null, null, 201);
68	        assertEquals("QUARANTINED", currentStatus(batchKey));
69	        submitTest(batchKey, testReq("TK-2", "含量", "PASS", "inspect-b"), null, null, 201);
70	        assertEquals("QUARANTINED", currentStatus(batchKey));
71	        submitTest(batchKey, testReq("TK-3", "无菌", "PASS", "inspect-c"), null, null, 201);
72	        assertEquals("PENDING_RELEASE", currentStatus(batchKey));
73	
74	        approve(batchKey, "qa-1", "QUALITY", "CK-AP-1", 201);
75	        assertEquals("RELEASE_REVIEW", currentStatus(batchKey));
76	        approve(batchKey, "ops-1", "OPERATIONS", "CK-AP-2", 201);
77	        assertEquals("RELEASED", currentStatus(batchKey));
