85	                .andExpect(status().isOk()).andReturn();
86	        JsonNode history = objectMapper.readTree(historyResult.getResponse().getContentAsString());
87	        assertEquals(3, history.path("tests").size());
88	        assertEquals(2, history.path("approvals").size());
89	        assertEquals("RECALLED", history.path("batch").path("status").asText());
90	        assertEquals("客户投诉，疑似污染", history.path("recall").path("reason").asText());
91	        assertEquals("RELEASED", history.path("approvals").get(1).path("batchStatus").asText());
