533	        MvcResult replay = mockMvc.perform(post("/api/batches/" + child + "/tests")
534	                        .contentType(MediaType.APPLICATION_JSON)
535	                        .content(objectMapper.writeValueAsString(
536	                                new TestCmd("CK-RP-T2", testKey, "t1", "PASS", "insp-2"))))
537	                .andExpect(status().isOk()).andReturn();
538	        assertEquals("PENDING_RELEASE", objectMapper
539	                .readTree(replay.getResponse().getContentAsString()).path("batchStatus").asText());
540	        // 但新增检验仍被拦截
541	        submitTest(child, "t1", "PASS", "insp-3", 422);
542	    }
